 document.addEventListener('change',ev=>{if(ev.target.id==='workStage'){stageFilter=ev.target.value;renderWorkList()}if(ev.target.id==='actorSelect'){capture();actor=ev.target.value;renderDialog()}if(ev.target.id==='resourceUpload')upload(ev.target.files[0]);if(ev.target.dataset.person){capture();let id=ev.target.dataset.person;if(ev.target.checked){if(!draft.team.some(m=>m.personId===id)){draft.team.push({personId:id,role:''});draft.tasks.forEach(t=>t.allocations[id]=0)}}else{if(draft.team.length===1){notify('至少保留一位成员');return renderDialog()}draft.team=draft.team.filter(m=>m.personId!==id);draft.tasks.forEach(t=>delete t.allocations[id]);delete draft.bonuses[id]}renderDialog()}});
 Q('#workClose').onclick=closeWork;Q('#workOverlay').onclick=e=>{if(e.target===Q('#workOverlay'))closeWork()};document.addEventListener('keydown',e=>{if(Q('#workOverlay').hidden)return;if(e.key==='Escape'){e.preventDefault();closeWork()}if(e.key==='Tab'){let es=QA('#workDialog button:not(:disabled),#workDialog input:not(:disabled),#workDialog select:not(:disabled),#workDialog textarea:not(:disabled),#workDialog a').filter(x=>x.offsetParent!==null&&!x.closest('fieldset:disabled'));let first=es[0],last=es.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
